FeatureScript 3070;
import(path:"onshape/std/common.fs",version:"3070.0");
function makeBox(context is Context,partId is Id,minimum is Vector,maximum is Vector){fCuboid(context,partId,{"corner1":minimum*millimeter,"corner2":maximum*millimeter});}
function makeCylinder(context is Context,partId is Id,start is number,end is number,center is array,radius is number){fCylinder(context,partId,{"bottomCenter":vector(start,center[0],center[1])*millimeter,"topCenter":vector(end,center[0],center[1])*millimeter,"radius":radius*millimeter});}
function labelPart(context is Context,partId is Id,name is string){setProperty(context,{"entities":qCreatedBy(partId,EntityType.BODY),"propertyType":PropertyType.NAME,"value":name});}
function drilledPlate(context is Context,partId is Id,start is number,end is number,rear is number){makeBox(context,partId+"stock",vector(start,0,12.7),vector(end,320,162.7));const holes=[[70,65,12.9],[rear,65,12.9],[140,135,6.6],[300,135,6.6],[25,130,12.9]];var cutters=[];for(var index=0;index<size(holes);index+=1){const cutterId=partId+("hole"~index);const hole=holes[index];makeCylinder(context,cutterId,start-1,end+1,[hole[0],hole[1]],hole[2]/2);cutters=append(cutters,qCreatedBy(cutterId,EntityType.BODY));}opBoolean(context,partId+"drill",{"targets":qCreatedBy(partId+"stock",EntityType.BODY),"tools":qUnion(cutters),"operationType":BooleanOperationType.SUBTRACTION});}
function makeTube(context is Context,partId is Id,length is number,center is array,outer is number,inner is number){makeCylinder(context,partId+"outside",-length/2,length/2,center,outer/2);if(inner>0){makeCylinder(context,partId+"bore",-length/2-1,length/2+1,center,inner/2);opBoolean(context,partId+"hollow",{"targets":qCreatedBy(partId+"outside",EntityType.BODY),"tools":qCreatedBy(partId+"bore",EntityType.BODY),"operationType":BooleanOperationType.SUBTRACTION});}}
function emit(tag is string,values is array){var text="OIM1|"~tag;for(var value in values)text=text~"|"~value;println(text);}
function measure(context is Context,featureId is Id,roles is array){for(var role in roles){const bodies=qBodyType(qCreatedBy(featureId+role,EntityType.BODY),BodyType.SOLID);const bounds=evBox3d(context,{"topology":bodies,"tight":true});const minimum=bounds.minCorner/millimeter;const maximum=bounds.maxCorner/millimeter;emit("P|"~role,[size(evaluateQuery(context,bodies)),evVolume(context,{"entities":bodies})/millimeter^3,minimum[0],minimum[1],minimum[2],maximum[0],maximum[1],maximum[2]]);const faces=evaluateQuery(context,qGeometry(qOwnedByBody(bodies,EntityType.FACE),GeometryType.CYLINDER));for(var face in faces){const surface=evSurfaceDefinition(context,{"face":face});const origin=surface.coordSystem.origin/millimeter;const axis=surface.coordSystem.zAxis;const limits=evBox3d(context,{"topology":face,"tight":true});const low=limits.minCorner/millimeter;const high=limits.maxCorner/millimeter;emit("C|"~role,[surface.radius/millimeter,origin[0],origin[1],origin[2],axis[0],axis[1],axis[2],low[0],low[1],low[2],high[0],high[1],high[2]]);}}emit("END",[size(evaluateQuery(context,qBodyType(qCreatedBy(featureId,EntityType.BODY),BodyType.SOLID)))]);}
