export const officialIntakeFinal = defineFeature(function(context is Context,id is Id,definition is map)precondition{}{const width=definition.innerWidth;const thickness=definition.plateThickness;const rear=146.2+definition.rollerGap;const roles=["leftPlate","rightPlate","frontRoller","rearRoller","frontShaft","rearShaft","frontCrossmember","rearCrossmember","coralReference"];drilledPlate(context,id+"leftPlate",-width/2-thickness,-width/2,rear);drilledPlate(context,id+"rightPlate",width/2,width/2+thickness,rear);const rollerLength=width-10;const shaftLength=width+2*thickness+25.4;makeTube(context,id+"frontRoller",rollerLength,[70,65],76.2,12.7);makeTube(context,id+"rearRoller",rollerLength,[rear,65],76.2,12.7);makeTube(context,id+"frontShaft",shaftLength,[70,65],12.7,0);makeTube(context,id+"rearShaft",shaftLength,[rear,65],12.7,0);makeBox(context,id+"frontCrossmember",vector(-width/2,127.3,122.3),vector(width/2,152.7,147.7));makeBox(context,id+"rearCrossmember",vector(-width/2,287.3,122.3),vector(width/2,312.7,147.7));makeTube(context,id+"coralReference",301.625,[-110,57.15],114.3,101.6);for(var role in roles)labelPart(context,id+role,role);setProperty(context,{"entities":qCreatedBy(id+"coralReference",EntityType.BODY),"propertyType":PropertyType.EXCLUDE_FROM_BOM,"value":true});emit("BEGIN",[width,definition.rollerGap,thickness]);measure(context,id,roles);},{"innerWidth":340,"rollerGap":100,"plateThickness":6.35});
